{
  "$schema": "https://docs.renovatebot.com/renovate-schema.json",
  "extends": [
    "local>basher83/renovate-config"
  ]
}

{
  "$schema": "https://docs.renovatebot.com/renovate-schema.json",
  "description": "Kubernetes preset - manages K8s manifests, Helm charts, Kustomize, Talhelper, with security-first approach",
  "kubernetes": {
    "fileMatch": [
      "/k8s/.+\\.ya?ml$/",
      "/kubernetes/.+\\.ya?ml$/",
      "/manifests/.+\\.ya?ml$/",
      "/deploy/.+\\.ya?ml$/"
    ]
  },
  "customManagers": [
    {
      "customType": "regex",
      "description": "Update Talos version in talconfig.yaml (Talhelper)",
      "fileMatch": [
        "/(^|/)talconfig\\.ya?ml$/"
      ],
      "matchStrings": [
        "talosVersion:\\s*['\"]?(?<currentValue>v[\\d.]+)['\"]?"
      ],
      "depNameTemplate": "siderolabs/talos",
      "datasourceTemplate": "github-releases"
    },
    {
      "customType": "regex",
      "description": "Update Kubernetes version in talconfig.yaml (Talhelper)",
      "fileMatch": [
        "/(^|/)talconfig\\.ya?ml$/"
      ],
      "matchStrings": [
        "kubernetesVersion:\\s*['\"]?(?<currentValue>v[\\d.]+)['\"]?"
      ],
      "depNameTemplate": "kubernetes/kubernetes",
      "datasourceTemplate": "github-releases"
    }
  ],
  "packageRules": [
    {
      "description": "Group Kubernetes manifest image updates",
      "matchManagers": [
        "kubernetes"
      ],
      "groupName": "Kubernetes Images"
    },
    {
      "description": "Auto-merge Helm chart patch updates (PR merge)",
      "matchManagers": [
        "helmv3",
        "helm-values"
      ],
      "matchUpdateTypes": [
        "patch"
      ],
      "automerge": true
    },
    {
      "description": "Group Helm chart minor updates for Monday review",
      "matchManagers": [
        "helmv3",
        "helm-values"
      ],
      "matchUpdateTypes": [
        "minor"
      ],
      "groupName": "Helm Charts (Minor)",
      "schedule": [
        "before 5am on Monday"
      ]
    },
    {
      "description": "Require approval for Helm chart major updates",
      "matchManagers": [
        "helmv3",
        "helm-values"
      ],
      "matchUpdateTypes": [
        "major"
      ],
      "dependencyDashboardApproval": true
    },
    {
      "description": "Auto-merge Kustomize patch updates (PR merge)",
      "matchManagers": [
        "kustomize"
      ],
      "matchUpdateTypes": [
        "patch"
      ],
      "automerge": true
    },
    {
      "description": "Group Kustomize minor updates for Monday review",
      "matchManagers": [
        "kustomize"
      ],
      "matchUpdateTypes": [
        "minor"
      ],
      "groupName": "Kustomize Dependencies (Minor)",
      "schedule": [
        "before 5am on Monday"
      ]
    },
    {
      "description": "Require approval for Kustomize major updates",
      "matchManagers": [
        "kustomize"
      ],
      "matchUpdateTypes": [
        "major"
      ],
      "dependencyDashboardApproval": true
    },
    {
      "description": "Pin container images to digests in Kubernetes manifests",
      "matchManagers": [
        "kubernetes"
      ],
      "pinDigests": true
    },
    {
      "description": "Auto-merge container digest updates in Kubernetes manifests (PR merge)",
      "matchManagers": [
        "kubernetes"
      ],
      "matchUpdateTypes": [
        "digest"
      ],
      "groupName": "Kubernetes Digests",
      "automerge": true
    },
    {
      "description": "Auto-merge container patch updates in Kubernetes manifests (PR merge)",
      "matchManagers": [
        "kubernetes"
      ],
      "matchUpdateTypes": [
        "patch"
      ],
      "automerge": true
    },
    {
      "description": "Require approval for critical infrastructure images",
      "matchManagers": [
        "kubernetes",
        "kustomize",
        "helmv3",
        "helm-values"
      ],
      "matchUpdateTypes": [
        "minor",
        "major"
      ],
      "matchPackageNames": [
        "/^postgres/",
        "/^mysql/",
        "/^redis/",
        "/^mongo/",
        "/^elasticsearch/",
        "/^rabbitmq/",
        "/^kafka/",
        "/^nginx/",
        "/^traefik/",
        "/^envoyproxy/",
        "/^istio/",
        "/^linkerd/",
        "/^vault/",
        "/^consul/"
      ],
      "dependencyDashboardApproval": true
    },
    {
      "description": "Label Kubernetes PRs",
      "matchManagers": [
        "kubernetes",
        "kustomize",
        "helmv3",
        "helm-values"
      ],
      "addLabels": [
        "kubernetes",
        "infrastructure"
      ]
    },
    {
      "description": "Group Talos cluster updates together",
      "matchDepNames": [
        "siderolabs/talos",
        "kubernetes/kubernetes"
      ],
      "groupName": "Talos Cluster"
    },
    {
      "description": "Auto-merge Talos patch updates (PR merge)",
      "matchDepNames": [
        "siderolabs/talos"
      ],
      "matchUpdateTypes": [
        "patch"
      ],
      "automerge": true
    },
    {
      "description": "Require approval for Talos minor/major updates",
      "matchDepNames": [
        "siderolabs/talos"
      ],
      "matchUpdateTypes": [
        "minor",
        "major"
      ],
      "dependencyDashboardApproval": true
    },
    {
      "description": "Require approval for Kubernetes version updates (Talos clusters)",
      "matchDepNames": [
        "kubernetes/kubernetes"
      ],
      "matchUpdateTypes": [
        "minor",
        "major"
      ],
      "dependencyDashboardApproval": true
    },
    {
      "description": "Label Talos cluster PRs",
      "matchDepNames": [
        "siderolabs/talos",
        "kubernetes/kubernetes"
      ],
      "addLabels": [
        "talos",
        "kubernetes",
        "infrastructure"
      ]
    }
  ]
}

{
  "$schema": "https://docs.renovatebot.com/renovate-schema.json",
  "description": "Example config for repos with custom Talos cluster layout (clusters/*.yaml with nested talos.version/kubernetes.version)",
  "extends": [
    "local>basher83/renovate-config",
    "local>basher83/renovate-config//presets/kubernetes.json"
  ],
  "customManagers": [
    {
      "customType": "regex",
      "description": "Update Talos version in cluster configs (nested talos.version format)",
      "fileMatch": [
        "/clusters/.+\\.ya?ml$/"
      ],
      "matchStrings": [
        "talos:\\s*\\n\\s*version:\\s*['\"]?(?<currentValue>v[\\d.]+)['\"]?"
      ],
      "depNameTemplate": "siderolabs/talos",
      "datasourceTemplate": "github-releases"
    },
    {
      "customType": "regex",
      "description": "Update Kubernetes version in cluster configs (nested kubernetes.version format)",
      "fileMatch": [
        "/clusters/.+\\.ya?ml$/"
      ],
      "matchStrings": [
        "kubernetes:\\s*\\n\\s*version:\\s*['\"]?(?<currentValue>v[\\d.]+)['\"]?"
      ],
      "depNameTemplate": "kubernetes/kubernetes",
      "datasourceTemplate": "github-releases"
    }
  ]
}

{
  "permissions": {
    "allow": [
      "Bash(gh api:*)",
      "WebFetch(domain:docs.renovatebot.com)"
    ]
  }
}

{
  "hooks": {
    "PostToolUse": [
      {
        "matcher": "Task",
        "hooks": [
          {
            "type": "command",
            "command": "sh -c 'if ! command -v entire >/dev/null 2>&1; then exit 0; fi; exec entire hooks claude-code post-task'"
          }
        ]
      },
      {
        "matcher": "TodoWrite",
        "hooks": [
          {
            "type": "command",
            "command": "sh -c 'if ! command -v entire >/dev/null 2>&1; then exit 0; fi; exec entire hooks claude-code post-todo'"
          }
        ]
      }
    ],
    "PreToolUse": [
      {
        "matcher": "Task",
        "hooks": [
          {
            "type": "command",
            "command": "sh -c 'if ! command -v entire >/dev/null 2>&1; then exit 0; fi; exec entire hooks claude-code pre-task'"
          }
        ]
      }
    ],
    "SessionEnd": [
      {
        "matcher": "",
        "hooks": [
          {
            "type": "command",
            "command": "sh -c 'if ! command -v entire >/dev/null 2>&1; then exit 0; fi; exec entire hooks claude-code session-end'"
          }
        ]
      }
    ],
    "SessionStart": [
      {
        "matcher": "",
        "hooks": [
          {
            "type": "command",
            "command": "sh -c 'if ! command -v entire >/dev/null 2>&1; then printf \"%s\\n\" \"{\\\"systemMessage\\\":\\\"\\\\n\\\\nEntire CLI is enabled but not installed or not on PATH.\\\\nInstallation guide: https://docs.entire.io/cli/installation#installation-methods\\\"}\"; exit 0; fi; exec entire hooks claude-code session-start'"
          }
        ]
      }
    ],
    "Stop": [
      {
        "matcher": "",
        "hooks": [
          {
            "type": "command",
            "command": "sh -c 'if ! command -v entire >/dev/null 2>&1; then exit 0; fi; exec entire hooks claude-code stop'"
          }
        ]
      }
    ],
    "UserPromptSubmit": [
      {
        "matcher": "",
        "hooks": [
          {
            "type": "command",
            "command": "sh -c 'if ! command -v entire >/dev/null 2>&1; then exit 0; fi; exec entire hooks claude-code user-prompt-submit'"
          }
        ]
      }
    ]
  },
  "permissions": {
    "deny": [
      "Read(./.entire/metadata/**)"
    ]
  }
}

{
  "enabled": true,
  "telemetry": true
}

// Entire CLI extension for Pi
// Auto-generated by `entire enable --agent pi`
// Do not edit manually — changes will be overwritten on next install.
//
// Forwards Pi lifecycle events to `entire hooks pi <event>` so Entire can
// create checkpoints, capture transcripts, and offer rewind/resume.
//
// ENTIRE_CMD is replaced at install time by Entire's installer.

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { execFile } from "node:child_process";

export default function (pi: ExtensionAPI) {
  const ENTIRE_CMD = "entire";
  let pendingSkillEvents: Array<{ skill_name: string; invocation: string; timestamp: string }> = [];

  // fireHook pipes data to `entire hooks pi <hookName>` and resolves with the
  // hook's stdout (empty string on any failure). Most hooks ignore the return;
  // before_agent_start uses it to apply a model-context injection.
  function fireHook(hookName: string, data: Record<string, unknown>): Promise<string> {
    return new Promise((resolve) => {
      try {
        const child = execFile(
          "sh",
          ["-c", `${ENTIRE_CMD} hooks pi ${hookName}`],
          { timeout: 10000, windowsHide: true, maxBuffer: 4 * 1024 * 1024 },
          (_err, stdout) => resolve(typeof stdout === "string" ? stdout : ""),
        );
        child.stdin?.end(JSON.stringify(data));
      } catch {
        // best effort — never block the agent on a hook failure
        resolve("");
      }
    });
  }

  // parseInjectedContext scans a hook's stdout for Entire's injection envelope
  // ({"inject_context":"..."}) and returns the text to inject, or null.
  function parseInjectedContext(stdout: string): string | null {
    if (!stdout) return null;
    for (const line of stdout.split("\n")) {
      const trimmed = line.trim();
      if (!trimmed.startsWith("{")) continue;
      try {
        const parsed = JSON.parse(trimmed) as { inject_context?: unknown };
        if (typeof parsed.inject_context === "string" && parsed.inject_context.length > 0) {
          return parsed.inject_context;
        }
      } catch {
        // not our envelope — ignore
      }
    }
    return null;
  }

  function parseSkillInvocation(text: string): { skill_name: string; invocation: string } | null {
    const match = text.trimStart().match(/^\/skill:([a-z0-9][a-z0-9-]{0,63})(?:\s|$)/);
    if (!match) return null;
    const invocation = text.trimStart().split(/\s+/, 1)[0] ?? `/skill:${match[1]}`;
    return { skill_name: match[1], invocation };
  }

  pi.on("input", async (event) => {
    const skill = parseSkillInvocation(event.text);
    if (skill) {
      pendingSkillEvents.push({ ...skill, timestamp: new Date().toISOString() });
    }
    return { action: "continue" };
  });

  // Agent-driven bash subprocesses inherit a real TTY but cannot answer
  // hook prompts. Disable git/Entire terminal prompts for bash calls so
  // Entire treats agent-driven commits as non-interactive.
  pi.on("tool_call", async (event) => {
    if (event.toolName !== "bash") return;
    const input = event.input as { command?: string };
    if (typeof input.command !== "string" || input.command.includes("GIT_TERMINAL_PROMPT=")) {
      return;
    }
    input.command = "export GIT_TERMINAL_PROMPT=0\n" + input.command;
  });

  pi.on("session_start", async (_event, ctx) => {
    await fireHook("session_start", {
      type: "session_start",
      cwd: ctx.cwd,
      session_file: ctx.sessionManager.getSessionFile(),
    });
  });

  pi.on("before_agent_start", async (event, ctx) => {
    const skillEvents = pendingSkillEvents;
    pendingSkillEvents = [];
    const stdout = await fireHook("before_agent_start", {
      type: "before_agent_start",
      cwd: ctx.cwd,
      session_file: ctx.sessionManager.getSessionFile(),
      prompt: event.prompt,
      skill_events: skillEvents,
    });
    const injected = parseInjectedContext(stdout);
    if (injected) {
      // Inject a hidden, persistent message so the model learns about Entire.
      // display:false keeps it out of the user-facing transcript while still
      // sending it to the LLM. Entire emits this at most once per session.
      return {
        message: {
          customType: "entire-context",
          content: injected,
          display: false,
        },
      };
    }
  });

  pi.on("agent_end", async (_event, ctx) => {
    await fireHook("agent_end", {
      type: "agent_end",
      cwd: ctx.cwd,
      session_file: ctx.sessionManager.getSessionFile(),
    });
  });

  pi.on("session_shutdown", async () => {
    await fireHook("session_shutdown", { type: "session_shutdown" });
  });
}
